import java.math.BigDecimal;

/**
 * The MHPCO claim rules: what the office reimburses for a damage report against
 * a policy, after the deductible and within the policy's payout cap.
 *
 * Two decisions the office revises on their own schedules meet here, in the
 * order the specification fixes: its clause book states how much of a damage
 * counts as reimbursable at all, and only then is the deductible borne. A new
 * clause or a revised threshold is the clause book's business; repricing the
 * deductible is this rule's.
 *
 * A payout is a payment out of the office, so its fraction of a G is rounded in
 * the office's favor by {@link InOfficesFavor}.
 */
public class ClaimPolicy {

    private static final BigDecimal DEDUCTIBLE_PER_DAMAGE = new BigDecimal("100");
    private static final BigDecimal UNRULY_ITEM_REIMBURSEMENT_RATE = new BigDecimal("0.5");

    /**
     * The office reimburses the reimbursable part of a damage less the
     * deductible, never below nothing.
     *
     * A damage smaller than the deductible earns nothing rather than owing the
     * office the difference, which is what the floor at nothing states. It is
     * load-bearing and not merely defensive: a 50 G damage would otherwise
     * reimburse -50 G, and the cap pays the lesser of a desired payout and what
     * it has left, so a negative payout would be paid out and would hand the
     * policy's cap 50 G back. A refused report is a separate matter, settled
     * before a reimbursement is ever computed in {@link Damage}.
     */
    public BigDecimal reimbursementFor(BigDecimal damageAmount, InsuredItem damagedItem) {
        return InOfficesFavor.payment(reimbursableDamageUnderClauses(damageAmount, damagedItem)
                .subtract(DEDUCTIBLE_PER_DAMAGE)
                .max(BigDecimal.ZERO));
    }

    /**
     * How much of a damage the office's clause book lets it count as
     * reimbursable, read from the damaged item and settled before the
     * deductible. The high-enchantment clause reimburses an unruly item's damage
     * at a reduced rate; a damage no clause speaks to counts in full.
     *
     * The office's second clause, that damage to an item of dragon material is
     * fully reimbursed, is absent here deliberately rather than by oversight: in
     * every case the specification states it grants exactly what a damage no
     * clause speaks to already earns. Below the unruly threshold it reimburses in
     * full, which is the default; at or above it the specification gives the
     * reduced rate precedence. So the clause never changes a reimbursement, and
     * the office does not record an item's material at all. A revision that gave
     * dragon material its own rate, or precedence over the high-enchantment
     * clause, would be the first to make the material worth recording.
     */
    private static BigDecimal reimbursableDamageUnderClauses(BigDecimal damageAmount,
            InsuredItem damagedItem) {
        if (damagedItem.isTooUnrulyToReimburseInFull()) {
            return damageAmount.multiply(UNRULY_ITEM_REIMBURSEMENT_RATE);
        }
        return damageAmount;
    }
}
=========== Coverage.java
import static java.util.stream.Collectors.counting;
import static java.util.stream.Collectors.groupingBy;

import java.util.List;
import java.util.Map;

/**
 * What a policy covers: the items the office recorded when it wrote the policy,
 * able to say which of them a reported damage is settled on.
 *
 * Reading a damage report against the covered items is a decision of its own,
 * revised on its own schedule and quite apart from what one damage earns or what
 * the cap allows.
 */
record Coverage(List<InsuredItem> insuredItems) {

    static Coverage of(List<InsuredItem> insuredItems) {
        return new Coverage(List.copyOf(insuredItems));
    }

    /**
     * What the office requires of an incident before it settles any of it: the
     * damages reported of a kind can be no more than the items of that kind the
     * policy covers, because each damage reported is a separate damage to a
     * separate covered item. An incident reporting more is no claim the office
     * will settle, and it refuses the claim whole rather than settling the part
     * it does cover.
     */
    void requireIncidentIsCovered(List<Damage> damages) {
        for (Map.Entry<String, Long> reported : countedByKind(damages).entrySet()) {
            if (reported.getValue() > coveredOfKind(reported.getKey())) {
                throw new RejectedScenario("the policy covers fewer items of type "
                        + reported.getKey() + " than the incident reports damaged");
            }
        }
    }

    /**
     * How many damages the incident reports of each kind of item. The kind is
     * read from the damage report verbatim, as {@link #isOfKind} reads it of a
     * covered item, so that the two sides of the comparison count the same kinds.
     */
    private static Map<String, Long> countedByKind(List<Damage> damages) {
        return damages.stream().collect(groupingBy(Damage::itemType, counting()));
    }

    /** How many items of the kind a damage report names the policy covers. */
    private long coveredOfKind(String damagedItemType) {
        return insuredItems.stream()
                .filter(insuredItem -> isOfKind(insuredItem, damagedItemType))
                .count();
    }

    /**
     * The covered item whose terms a reported damage is settled on: the office
     * looks the reported kind of item up among the items it covers, and the
     * claim rules read the clauses from it. A damage naming a kind of item the
     * coverage does not include is no claim the office will settle.
     *
     * The office matches by the kind of item reported. Several covered items of
     * one kind are alike in everything the claim rules read, so which of them a
     * damage is settled on cannot change what it earns; what matters is that
     * there are enough of them, which
     * {@link #requireIncidentIsCovered} has already established.
     */
    InsuredItem itemDamagedBy(Damage damage) {
        for (InsuredItem insuredItem : insuredItems) {
            if (isOfKind(insuredItem, damage.itemType())) {
                return insuredItem;
            }
        }
        throw new RejectedScenario(
                "the policy does not cover an item of type " + damage.itemType());
    }

    /**
     * Whether a covered item is of the kind a damage report names, which is all
     * the office asks of a covered item to settle a damage on it. Recognizing a
     * damage by something narrower than the kind reported would be a revision of
     * this one sentence.
     */
    private static boolean isOfKind(InsuredItem insuredItem, String damagedItemType) {
        return insuredItem.type().equals(damagedItemType);
    }
}

=========== Customer.java
/**
 * The customer a scenario is about, as the office knows them: their standing
 * with the MHPCO at the moment a premium is quoted.
 *
 * Both facts here are the office's view of its relationship with this customer
 * rather than of the items insured, so this is also where the office decides
 * what that relationship entitles the customer to: whether they count as
 * long-standing, and whether this contract is a follow-up. The rates those
 * entitlements earn are the premium rules' business, in {@link PremiumPolicy}.
 */
public record Customer(int yearsWithMHPCO, int contractsAlreadyHeld) {

    private static final int LOYALTY_YEARS = 2;

    /**
     * The office counts a customer as long-standing from 2 years of business
     * with the MHPCO up; a newer customer earns no loyalty.
     */
    public boolean isLongStanding() {
        return yearsWithMHPCO >= LOYALTY_YEARS;
    }

    /**
     * Every contract after the customer's first is a follow-up, however long
     * they have been with the office.
     */
    public boolean holdsFollowUpContract() {
        return contractsAlreadyHeld > 0;
    }
}
=========== Damage.java
import java.math.BigDecimal;

/**
 * One damage the customer reports: which kind of item was damaged, and by how
 * much.
 *
 * A report the office will not read at all is refused here rather than settled
 * later, because it is refused on the report alone. The other refusals the
 * office issues — an item not on the price list, a kind the policy does not
 * cover, more damages of a kind than items covered — each need records this
 * report knows nothing of, so each belongs with the records it reads. What makes
 * a report no damage at all is this report's own business, and
 * {@link #requireIsHarmDone} is the one sentence a revision would touch.
 */
public record Damage(String itemType, BigDecimal amount) {

    public Damage {
        requireIsHarmDone(amount);
    }

    /**
     * A damage is harm done, so an amount below nothing is no damage the office
     * will read. Refusing a further kind of report — harm of exactly nothing,
     * say — would be a revision of this one sentence.
     */
    private static void requireIsHarmDone(BigDecimal amount) {
        if (amount.signum() < 0) {
            throw new RejectedScenario(
                    "a damage of " + amount + " G is no damage the MHPCO can read");
        }
    }
}
=========== InOfficesFavor.java
import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * The MHPCO rounds every amount to whole G in its own favor. One rule, read in
 * the direction the money moves: a fraction of a G the customer owes the office
 * is rounded up, a fraction the office owes the customer is rounded down. The
 * office never loses the fraction.
 *
 * Intermediate amounts during a calculation stay exact fractions; only a final
 * charge or payment is rounded.
 */
final class InOfficesFavor {

    private static final int WHOLE_G = 0;

    private InOfficesFavor() {
    }

    /** What the customer owes the office, rounded up: the fraction favors the office. */
    static BigDecimal charge(BigDecimal amount) {
        return amount.setScale(WHOLE_G, RoundingMode.CEILING);
    }

    /** What the office owes the customer, rounded down: the fraction favors the office. */
    static BigDecimal payment(BigDecimal amount) {
        return amount.setScale(WHOLE_G, RoundingMode.FLOOR);
    }
}
=========== InsuredItem.java
/**
 * An item a policy covers, as the office records it.
 *
 * The office reads the recorded facts to classify the item's risk, so the
 * classifications live here with the facts they read, while what each risk
 * costs is the premium rules' business in {@link PremiumPolicy}. The
 * enchantment level carries more than one such classification: the premium
 * rules surcharge a high enchantment from level 5 up, and the claim rules have
 * their own, higher threshold, so each threshold is named for the rule it
 * serves rather than sharing one vague "enchanted" predicate.
 */
public record InsuredItem(String type, boolean cursed, int enchantment) {

    private static final int HIGH_ENCHANTMENT_LEVEL = 5;
    private static final int UNRULY_ENCHANTMENT_LEVEL = 8;

    /**
     * The office counts an item as highly enchanted, and so as carrying a risk
     * worth a surcharge, from enchantment level 5 up.
     */
    public boolean isHighlyEnchanted() {
        return enchantment >= HIGH_ENCHANTMENT_LEVEL;
    }

    /**
     * From enchantment level 8 up the office considers an item too unruly for
     * its damage to be reimbursed in full. What such a damage earns instead is
     * the claim rules' clause to state, in {@link ClaimPolicy}.
     */
    public boolean isTooUnrulyToReimburseInFull() {
        return enchantment >= UNRULY_ENCHANTMENT_LEVEL;
    }
}
=========== PayoutCap.java
import java.math.BigDecimal;

/**
 * The limit on everything a policy will ever pay out, and how much of it is
 * left. The office caps a policy at twice the insurance sum of the items it
 * covers.
 *
 * What the cap is worth and what it has left are one decision revised on its
 * own schedule: a revision to the multiple, or one that let the cap replenish,
 * is this cap's business and touches no claim rule. Premium modifiers are no
 * part of it, which is why a cap is opened from an insurance sum and never from
 * a premium.
 */
class PayoutCap {

    private static final BigDecimal CAP_MULTIPLE_OF_INSURANCE_SUM = new BigDecimal("2");

    private BigDecimal remaining;

    static PayoutCap forInsuranceSum(BigDecimal insuranceSum) {
        return new PayoutCap(insuranceSum.multiply(CAP_MULTIPLE_OF_INSURANCE_SUM));
    }

    private PayoutCap(BigDecimal remaining) {
        this.remaining = remaining;
    }

    /** Pays what the cap still allows of a desired payout and consumes that much of it. */
    BigDecimal pay(BigDecimal desiredPayout) {
        BigDecimal paid = desiredPayout.min(remaining);
        remaining = remaining.subtract(paid);
        return paid;
    }

    BigDecimal remaining() {
        return remaining;
    }
}
=========== Policy.java
import java.math.BigDecimal;
import java.util.List;

/**
 * A policy the office has written: the {@link Coverage} it was written over and
 * the {@link PayoutCap} it was written under.
 *
 * Settling an incident against the policy is this policy's decision, not the
 * protocol's, and all it decides is how the three parties to a settlement meet:
 * the coverage says which covered item a reported damage is settled on, the
 * {@link ClaimPolicy} says what that one damage earns, and the cap says how much
 * of it is actually paid. So the deductible is borne once per damage reported
 * and the cap is consumed in the order the damages are reported.
 */
public class Policy {

    private final Coverage coverage;
    private final PayoutCap payoutCap;

    /**
     * The office writes a policy over the items a customer brings: what it
     * insures them for is the {@link PriceList}'s to state, and the cap that
     * insurance sum earns is the cap's own rule. Premium modifiers are no part
     * of it, which is why the policy is written from the covered items and never
     * from the premium quoted for them.
     */
    public static Policy covering(List<InsuredItem> insuredItems, PriceList priceList) {
        return new Policy(Coverage.of(insuredItems),
                PayoutCap.forInsuranceSum(priceList.insuranceSum(insuredItems)));
    }

    private Policy(Coverage coverage, PayoutCap payoutCap) {
        this.coverage = coverage;
        this.payoutCap = payoutCap;
    }

    /**
     * What the office pays for one reported incident: the sum of what each
     * damage reported is settled for, settled in the order reported so that the
     * cap is consumed in that order. An incident the coverage refuses is settled
     * not at all, so nothing is paid out of a claim the office rejects.
     */
    public BigDecimal settle(List<Damage> damages, ClaimPolicy claimPolicy) {
        coverage.requireIncidentIsCovered(damages);
        BigDecimal paid = BigDecimal.ZERO;
        for (Damage damage : damages) {
            paid = paid.add(settleOne(damage, claimPolicy));
        }
        return paid;
    }

    /**
     * What one reported damage is actually paid: the coverage says which covered
     * item it is settled on, the claim rules say what that damage earns on that
     * item's terms, and the cap pays what it still allows of it.
     *
     * Every damage reported is settled here on its own, which is why a second
     * damage of a kind already damaged bears the deductible again and draws on
     * the cap the first one has already reduced. Settling an incident as a whole
     * instead — one deductible for the incident, or the incident's total tested
     * against the cap in one go — would be a revision of this one sentence.
     */
    private BigDecimal settleOne(Damage damage, ClaimPolicy claimPolicy) {
        InsuredItem damagedItem = coverage.itemDamagedBy(damage);
        return payoutCap.pay(claimPolicy.reimbursementFor(damage.amount(), damagedItem));
    }

    public BigDecimal remainingCap() {
        return payoutCap.remaining();
    }
}
=========== RejectedScenario.java
/**
 * The office refuses to deal with the scenario and says why. A refusal is the
 * office's answer to the whole scenario, not a result within it.
 *
 * Each refusal is raised where the office holds what it takes to decide it,
 * rather than gathered into one gate: the {@link PriceList} refuses an item it
 * does not list, a {@link Coverage} refuses a damage naming a kind it does not
 * cover and an incident reporting more damages of a kind than it covers items,
 * and a {@link Damage} refuses a report that is no damage at all. The first
 * three read records the report knows nothing of; the last is decided on the
 * report alone, which is why it sits with the report and the others do not.
 */
public class RejectedScenario extends RuntimeException {

    private static final long serialVersionUID = 1L;

    public RejectedScenario(String reason) {
        super(reason);
    }
}

=========== PremiumPolicy.java
import java.math.BigDecimal;
import java.util.List;

/**
 * The MHPCO premium rules: the two scopes of premium modifier, the processing
 * fee, applied to the base premium the {@link PriceList} states for the insured
 * items.
 *
 * A premium is a charge to the customer, so its fraction of a G is rounded in
 * the office's favor by {@link InOfficesFavor}.
 */
public class PremiumPolicy {

    private static final BigDecimal CURSE_SURCHARGE_RATE = new BigDecimal("0.50");
    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE_RATE = new BigDecimal("0.30");
    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = new BigDecimal("0.10");
    private static final BigDecimal LOYALTY_DISCOUNT_RATE = new BigDecimal("0.20");
    private static final BigDecimal FOLLOW_UP_CONTRACT_DISCOUNT_RATE = new BigDecimal("0.15");
    private static final BigDecimal PROCESSING_FEE = new BigDecimal("5");

    private final PriceList priceList;

    /** The premium rules read their base premiums from the office's price list. */
    public PremiumPolicy(PriceList priceList) {
        this.priceList = priceList;
    }

    /**
     * The office charges both kinds of modifier on a base premium, never on each
     * other: an item modifier on the affected item's own base premium, a
     * policy-wide modifier on the policy base premium. So the two are summed
     * alongside the base premium rather than compounded in sequence, and the
     * processing fee is added at the very end.
     */
    public int quote(Customer customer, List<InsuredItem> insuredItems) {
        BigDecimal policyBasePremium = priceList.policyBasePremium(insuredItems);
        BigDecimal premium = policyBasePremium
                .add(itemRiskSurcharges(insuredItems))
                .add(policyWideModifiers(policyBasePremium, customer))
                .add(PROCESSING_FEE);
        return InOfficesFavor.charge(premium).intValueExact();
    }

    /**
     * Item-scope modifiers: each is charged on the base premium of the affected
     * item alone, so a modifier on one item never touches another item's share
     * of the policy. What one item's risks cost is {@link #riskSurcharge}'s
     * business; this rule only states that the policy owes the sum of them.
     */
    private BigDecimal itemRiskSurcharges(List<InsuredItem> insuredItems) {
        BigDecimal surcharges = BigDecimal.ZERO;
        for (InsuredItem insuredItem : insuredItems) {
            surcharges = surcharges.add(riskSurcharge(insuredItem));
        }
        return surcharges;
    }

    /**
     * What the risks the office reads in one item cost, charged on that item's
     * own base premium. A curse and a high enchantment are separate risks, so an
     * item carrying both is surcharged for both rather than letting the graver
     * risk absorb the other.
     */
    private BigDecimal riskSurcharge(InsuredItem insuredItem) {
        BigDecimal itemBasePremium = priceList.basePremium(insuredItem);
        BigDecimal surcharge = BigDecimal.ZERO;
        if (insuredItem.cursed()) {
            surcharge = surcharge.add(itemBasePremium.multiply(CURSE_SURCHARGE_RATE));
        }
        if (insuredItem.isHighlyEnchanted()) {
            surcharge = surcharge.add(itemBasePremium.multiply(HIGH_ENCHANTMENT_SURCHARGE_RATE));
        }
        return surcharge;
    }

    /**
     * Policy-scope modifiers: each is charged on the policy base premium, the
     * sum of all item base premiums. Every quote is a first insurance of the
     * items it covers, whatever the customer's history.
     */
    private BigDecimal policyWideModifiers(BigDecimal policyBasePremium, Customer customer) {
        return firstInsuranceSurcharge(policyBasePremium)
                .subtract(loyaltyDiscount(policyBasePremium, customer))
                .subtract(followUpContractDiscount(policyBasePremium, customer));
    }

    /**
     * Every contract after the customer's first earns a discount, however long
     * they have been with the office.
     */
    private static BigDecimal followUpContractDiscount(BigDecimal policyBasePremium,
            Customer customer) {
        if (!customer.holdsFollowUpContract()) {
            return BigDecimal.ZERO;
        }
        return policyBasePremium.multiply(FOLLOW_UP_CONTRACT_DISCOUNT_RATE);
    }

    /**
     * Every quote is a first insurance of the items it covers, whatever the
     * customer's history, so this surcharge is charged on every policy.
     */
    private static BigDecimal firstInsuranceSurcharge(BigDecimal policyBasePremium) {
        return policyBasePremium.multiply(FIRST_INSURANCE_SURCHARGE_RATE);
    }

    /**
     * The office rewards a long-standing customer with a discount on the policy
     * base premium. Who counts as long-standing is the customer's standing to
     * answer; this rule only states what that standing is worth.
     */
    private static BigDecimal loyaltyDiscount(BigDecimal policyBasePremium, Customer customer) {
        if (!customer.isLongStanding()) {
            return BigDecimal.ZERO;
        }
        return policyBasePremium.multiply(LOYALTY_DISCOUNT_RATE);
    }
}
=========== PriceList.java
import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The MHPCO price list: one published tariff row per insurable item type,
 * stating what the office charges as that item's base premium and what it
 * insures the item for. Main items are listed individually; every component
 * shares one row, because the office prices and insures a rune exactly as it
 * does a moonstone, and a building block of alike components is offered at a
 * special rate.
 *
 * The block rate is the one tariff decision that is not a property of a single
 * item: a block is a quantity of <em>alike</em> components, so the tariff also
 * decides which items count as alike (see {@link #alikenessGroupOf}) and groups
 * them before pricing. It groups for pricing only: the insured values are read
 * per item, because an offer on what the office charges is no revaluation of
 * what it insures.
 *
 * This is the office's tariff. It changes on its own schedule, independently of
 * the modifier rules in {@link PremiumPolicy}.
 */
public class PriceList {

    /**
     * What the office charges and insures for one item type. The two figures
     * are revised on their own schedules — a rate revision repricing premiums
     * need not revalue the items — but they are published together, as one row
     * of the price list, because they describe the same insured thing.
     */
    private record Tariff(BigDecimal basePremium, BigDecimal insuranceValue) {
    }

    /** Every component is charged and insured alike, whatever its type. */
    private static final Tariff COMPONENT_TARIFF =
            new Tariff(new BigDecimal("25"), new BigDecimal("250"));

    /** The published price list: the item types the office insures, and at what. */
    private static final Map<String, Tariff> TARIFF = Map.of(
            "sword", new Tariff(new BigDecimal("100"), new BigDecimal("1000")),
            "amulet", new Tariff(new BigDecimal("60"), new BigDecimal("600")),
            "staff", new Tariff(new BigDecimal("80"), new BigDecimal("800")),
            "potion", new Tariff(new BigDecimal("40"), new BigDecimal("400")),
            "rune", COMPONENT_TARIFF,
            "moonstone", COMPONENT_TARIFF);

    /**
     * Which of the insured types the office regards as components rather than
     * main items. Only the block offer asks: a component's own figures are read
     * from its tariff row like any other item's.
     */
    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");

    /** A building block of exactly 3 alike components is offered at this rate. */
    private static final BigDecimal COMPONENT_BLOCK_BASE_PREMIUM = new BigDecimal("60");
    private static final int COMPONENT_BLOCK_SIZE = 3;

    /**
     * The insurance sum of a policy: the sum of its items' insurance values,
     * each item valued on its own.
     *
     * This deliberately asks nothing about holdings, while
     * {@link #policyBasePremium} prices alike items together. The two figures of
     * a tariff row are read on different terms because the block rate is an
     * offer on what the office <em>charges</em>, not a revaluation of what it
     * <em>insures</em>: a block of 3 runes is charged 60 G but still insured for
     * 3 x 250 G, so the cap it earns is untouched by the discount. Any future
     * holding-dependent offer belongs in the premium fold alone; a revision that
     * also revalued a holding would be the first to group items here.
     */
    public BigDecimal insuranceSum(List<InsuredItem> insuredItems) {
        BigDecimal total = BigDecimal.ZERO;
        for (InsuredItem insuredItem : insuredItems) {
            total = total.add(tariffFor(insuredItem.type()).insuranceValue());
        }
        return total;
    }

    /**
     * The base premium for all items a policy covers, alike items priced
     * together because the block rate is an offer on a holding rather than on a
     * single item. This is the one fold that groups: {@link #insuranceSum}
     * values each item on its own, as the block offer leaves the insured values
     * alone.
     */
    public BigDecimal policyBasePremium(List<InsuredItem> insuredItems) {
        BigDecimal total = BigDecimal.ZERO;
        for (Map.Entry<String, Integer> alikeItems : groupedByAlikeness(insuredItems).entrySet()) {
            total = total.add(basePremium(alikeItems.getKey(), alikeItems.getValue()));
        }
        return total;
    }

    /**
     * The base premium of one insured item on its own, which is what an
     * item-specific surcharge such as the curse surcharge is charged on. A
     * component priced within a block is not charged on its own.
     */
    public BigDecimal basePremium(InsuredItem insuredItem) {
        return basePremium(insuredItem.type(), 1);
    }

    private static Map<String, Integer> groupedByAlikeness(List<InsuredItem> insuredItems) {
        Map<String, Integer> counts = new LinkedHashMap<>();
        for (InsuredItem insuredItem : insuredItems) {
            counts.merge(alikenessGroupOf(insuredItem.type()), 1, Integer::sum);
        }
        return counts;
    }

    /**
     * The office counts two items as alike when they are of exactly the same
     * type, not merely of the same family: 2 runes and a moonstone are three
     * loose components priced at 75 G, never a block, because a moonstone is not
     * a rune. Widening "alike" to a family (rune-y, gemstone-y) would mean
     * returning a family name here instead of the type itself.
     */
    private static String alikenessGroupOf(String itemType) {
        return itemType;
    }

    /**
     * The tariff row for an item type. The office insures only the items on its
     * price list, so an item it does not recognize is no business of its own.
     */
    private static Tariff tariffFor(String itemType) {
        Tariff tariff = TARIFF.get(itemType);
        if (tariff == null) {
            throw new RejectedScenario("the MHPCO does not insure items of type " + itemType);
        }
        return tariff;
    }

    /**
     * What a holding of alike items of one type costs: the type's own rate per
     * item, except that a block of components is offered at the block rate.
     */
    private static BigDecimal basePremium(String itemType, int count) {
        if (qualifiesForBlockRate(itemType, count)) {
            return COMPONENT_BLOCK_BASE_PREMIUM;
        }
        return tariffFor(itemType).basePremium().multiply(BigDecimal.valueOf(count));
    }

    /**
     * The office grants the block rate only to a holding of exactly 3 alike
     * components. It neither prices a part of a block at the block rate (4
     * components are not a block) nor breaks a larger holding down into blocks
     * (7 components are priced as 7, not as two blocks and one loose component).
     * Main items are never blocked: 3 swords are 3 swords.
     */
    private static boolean qualifiesForBlockRate(String itemType, int alikeItemCount) {
        return COMPONENT_TYPES.contains(itemType) && alikeItemCount == COMPONENT_BLOCK_SIZE;
    }
